/**
 * @method
 * @name bydfi#fetchOrderBook
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://developers.bydfi.com/en/futures/market#depth-information
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return, could be 5, 10, 20, 50, 100, 500 or 1000 (default 500)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.loc] crypto location, default: us
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Bydfi) FetchOrderBookAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bydfi) fetchOrderBookBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	if limit != nil {
		request["limit"] = this.GetClosestLimit(limit)
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetV1FapiMarketDepth(this.Extend(request, params))).Raw))
	//
	//     {
	//         "code": 200,
	//         "message": "success",
	//         "data": {
	//             "lastUpdateId": "221780076",
	//             "symbol": "ETH-USDT",
	//             "asks": [
	//                 {
	//                     "price": "2958.21",
	//                     "amount": "39478"
	//                 },
	//                 ...
	//             ],
	//             "bids": [
	//                 {
	//                     "price": "2958.19",
	//                     "amount": "174498"
	//                 },
	//                 ...
	//             ],
	//             "e": "221780076"
	//         },
	//         "success": true
	//     }
	//
	var data map[string]any = MapTyped(this.SafeDict(response, "data", map[string]any{}))
	var orderBook map[string]any = this.ParseOrderBook(data, market["symbol"], nil, "bids", "asks", "price", "amount")
	orderBook["nonce"] = this.SafeInteger(data, "lastUpdateId")

	ch <- orderBook
	return nil
}
func (this *Bydfi) GetClosestLimit(limit any) any {
	var limits []any = []any{5, 10, 20, 50, 100, 500, 1000}
	var result any = 1000
	for i := 0; i < len(limits); i++ {
		if IsEqual(limit, nil) {
			panic(ArgumentsRequired(this.Id + " getClosestLimit() requires a limit argument"))
		}
		if IsLessThanOrEqual(limit, func() any {
			if i >= 0 && i < len(limits) {
				return DerefScalar(limits[i])
			}
			return nil
		}()) {
			result = func() any {
				if i >= 0 && i < len(limits) {
					return DerefScalar(limits[i])
				}
				return nil
			}()
			break
		}
	}
	return result
}

