/**
 * @method
 * @name bydfi#fetchMyTrades
 * @description fetch all trades made by the user
 * @see https://developers.bydfi.com/en/futures/trade#historical-trades-query
 * @param {string} symbol unified market symbol
 * @param {int} [since] the earliest time in ms to fetch trades for
 * @param {int} [limit] the maximum number of trades structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] the latest time in ms to fetch trades for
 * @param {string} [params.contractType] FUTURE or DELIVERY, default is FUTURE
 * @param {string} [params.wallet] The unique code of a sub-wallet
 * @param {string} [params.orderType] order type ('LIMIT', 'MARKET', 'LIQ', 'LIMIT_CLOSE', 'MARKET_CLOSE', 'STOP', 'TAKE_PROFIT', 'STOP_MARKET', 'TAKE_PROFIT_MARKET' or 'TRAILING_STOP_MARKET')
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
 */
func (this *Bydfi) FetchMyTradesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Bydfi) fetchMyTradesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var paginate *bool = this.SafeBool(params, "paginate", false)
	if paginate != nil && *paginate == true {
		var maxLimit int = 500
		var paramsPaginate map[string]any = this.Extend(this.Omit(params, "paginate"), map[string]any{
			"paginationDirection": "backward",
		})

		var paginatedResponse []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallDynamicAsync("fetchMyTrades", symbol, since, limit, paramsPaginate, maxLimit, true))))

		ch <- this.SortBy(paginatedResponse, "timestamp")
		return nil
	}
	contractType, paramsContractType := this.HandleOptionStringAndParams(params, "fetchMyTrades", "contractType", "FUTURE")
	var request map[string]any = map[string]any{
		"contractType": contractType,
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
		request["symbol"] = GetValue(market, "id")
	}
	var paramsSinceUntil any = this.HandleSinceAndUntil("fetchMyTrades", since, paramsContractType)
	if limit != nil {
		request["limit"] = limit
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivateGetV1FapiTradeHistoryTrade(this.Extend(request, paramsSinceUntil))).Raw))
	//
	//     {
	//         "code": 200,
	//         "message": "success",
	//         "data": [
	//             {
	//                 "orderId": "7408919189505597440",
	//                 "wallet": "W001",
	//                 "symbol": "ETH-USDC",
	//                 "time": "1766423985842",
	//                 "dealPrice": "3032.45",
	//                 "dealVolume": "1",
	//                 "fee": "0",
	//                 "side": "BUY",
	//                 "type": "2",
	//                 "liqPrice": null,
	//                 "basePrecision": "8",
	//                 "baseShowPrecision": "2",
	//                 "tradePnl": "0",
	//                 "marginType": "CROSS",
	//                 "leverageLevel": 1
	//             }
	//         ],
	//         "success": true
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseTrades(data, market, since, limit)
	return nil
}
func (this *Bydfi) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades
	//     {
	//         "id": "7407825178362667008",
	//         "symbol": "ETH-USDT",
	//         "price": "2970.49",
	//         "quantity": "63",
	//         "side": "SELL",
	//         "time": 1766163153218
	//     }
	//
	// fetchMyTrades
	//     {
	//         "orderId": "7408919189505597440",
	//         "wallet": "W001",
	//         "symbol": "ETH-USDC",
	//         "time": "1766423985842",
	//         "dealPrice": "3032.45",
	//         "dealVolume": "1",
	//         "fee": "0",
	//         "side": "BUY",
	//         "type": "2",
	//         "liqPrice": null,
	//         "basePrecision": "8",
	//         "baseShowPrecision": "2",
	//         "tradePnl": "0",
	//         "marginType": "CROSS",
	//         "leverageLevel": 1
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(trade, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(trade, "time")
	var fee map[string]any = nil
	var rawType *string = this.SafeString(trade, "type")
	var feeCost *string = this.SafeString(trade, "fee")
	if feeCost != nil {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": marketResolved["settle"],
		}
	}
	var orderId *string = this.SafeString(trade, "orderId")
	var side *string = nil // fetchMyTrades always returns side BUY
	if orderId == nil {
		// from fetchTrades
		side = this.SafeStringLower(trade, "side")
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       marketResolved["symbol"],
		"id":           this.SafeString(trade, "id"),
		"order":        orderId,
		"type":         this.ParseTradeType(rawType),
		"side":         side,
		"takerOrMaker": nil,
		"price":        this.SafeString2(trade, "price", "dealPrice"),
		"amount":       this.SafeString2(trade, "quantity", "dealVolume"),
		"cost":         nil,
		"fee":          fee,
	}, marketResolved)
}
func (this *Bydfi) ParseTradeType(typeVar *string) *string {
	var types map[string]any = map[string]any{
		"1": "limit",
		"2": "market",
		"3": "liquidation",
	}
	return this.SafeString(types, typeVar, typeVar)
}

/**
 * @method
 * @name bydfi#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://developers.bydfi.com/en/futures/market#candlestick-data
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch (max 500)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Bydfi) FetchOHLCVAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bydfi) fetchOHLCVBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var maxLimit int = 500 // docs says max 1500, but in practice only 500 works
	var paginateparamsPaginateVariable []any = this.HandleOptionBoolAndParams(params, "fetchOHLCV", "paginate", false)
	var paginate bool = GetValueBool(paginateparamsPaginateVariable, 0, false)
	var paramsPaginate map[string]any = MapTyped(GetValue(paginateparamsPaginateVariable, 1))
	if paginate {

		ch <- this.FetchPaginatedCallDeterministicAsync("fetchOHLCV", symbol, since, limit, timeframe, paramsPaginate, maxLimit)
		return nil
	}
	var market map[string]any = this.Market(symbol)
	var interval *string = this.SafeString(this.Timeframes, timeframe, timeframe)
	var request map[string]any = map[string]any{
		"symbol":   market["id"],
		"interval": interval,
	}
	var startTime any = since
	var numberOfCandles any = maxLimit
	if (limit != nil) && (limit == nil || *limit != 0) {
		numberOfCandles = limit
	}
	var until any = nil
	var paramsUntil any = nil
	var untilparamsUntilVariable []any = this.HandleOptionIntegerAndParams(paramsPaginate, "fetchOHLCV", "until")
	until = GetValue(untilparamsUntilVariable, 0)
	paramsUntil = GetValue(untilparamsUntilVariable, 1)
	var now int64 = this.Milliseconds()
	var duration int64 = this.ParseTimeframe(timeframe) * 1000
	var timeDelta any = Multiply(duration, numberOfCandles)
	if IsEqual(startTime, nil) && IsEqual(until, nil) {
		startTime = Subtract(now, timeDelta)
		until = now
	} else if IsEqual(until, nil) {
		if IsEqual(startTime, nil) {
			panic(ArgumentsRequired(this.Id + " fetchOHLCV() requires a since or until argument"))
		}
		until = Add(startTime, timeDelta)
		if IsGreaterThan(until, now) {
			until = now
		}
	} else if IsEqual(startTime, nil) {
		startTime = Subtract(until, timeDelta)
	}
	request["startTime"] = startTime
	request["endTime"] = until
	if limit != nil {
		request["limit"] = limit
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetV1FapiMarketKlines(this.Extend(request, paramsUntil))).Raw))
	//
	//     {
	//         "code": 200,
	//         "message": "success",
	//         "data": [
	//             {
	//                 "s": "ETH-USDT",
	//                 "t": "1766166000000",
	//                 "c": "2964.990000000000000000",
	//                 "o": "2967.830000000000000000",
	//                 "h": "2967.830000000000000000",
	//                 "l": "2964.130000000000000000",
	//                 "v": "20358.000000000000000000"
	//             }
	//         ],
	//         "success": true
	//     }
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})
	var result any = this.ParseOHLCVs(data, market, timeframe, since, limit)

	ch <- result
	return nil
}
func (this *Bydfi) ParseOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	//     {
	//         "s": "ETH-USDT",
	//         "t": "1766166000000",
	//         "c": "2964.990000000000000000",
	//         "o": "2967.830000000000000000",
	//         "h": "2967.830000000000000000",
	//         "l": "2964.130000000000000000",
	//         "v": "20358.000000000000000000"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return []any{this.SafeInteger(ohlcv, "t"), this.SafeNumber(ohlcv, "o"), this.SafeNumber(ohlcv, "h"), this.SafeNumber(ohlcv, "l"), this.SafeNumber(ohlcv, "c"), this.SafeNumber(ohlcv, "v")}
}

