/**
 * @method
 * @name bydfi#createOrder
 * @description create a trade order
 * @see https://developers.bydfi.com/en/futures/trade#placing-an-order
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fullfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.wallet] The unique code of a sub-wallet. W001 is the default wallet and the main wallet code of the contract
 * @param {bool} [params.hedged] true for hedged mode, false for one way mode, default is false
 * @param {string} [params.clientOrderId] Custom order ID, must be unique for open orders
 * @param {string} [params.timeInForce] 'GTC' (Good Till Cancelled), 'FOK' (Fill Or Kill), 'IOC' (Immediate Or Cancel), 'PO' (Post Only)
 * @param {bool} [params.postOnly] true or false, whether the order is post-only
 * @param {bool} [params.reduceOnly] true or false, true or false whether the order is reduce-only
 * @param {float} [params.stopLossPrice] The price a stop loss order is triggered at
 * @param {float} [params.takeProfitPrice] The price a take profit order is triggered at
 * @param {float} [params.trailingTriggerPrice] the price to activate a trailing order, default uses the price argument or market price if price is not provided
 * @param {float} [params.trailingPercent] the percent to trail away from the current market price
 * @param {string} [params.triggerPriceType] 'MARK_PRICE' or 'CONTRACT_PRICE', default is 'CONTRACT_PRICE', the price type used to trigger stop orders
 * @param {bool} [params.closePosition] true or false, whether to close all positions after triggering, only supported in STOP_MARKET and TAKE_PROFIT_MARKET; not used with quantity;
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bydfi) CreateOrderAsync(symbol any, typeVar string, side string, amount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Bydfi) createOrderBody(ch chan any, symbol any, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var orderRequest any = this.CreateOrderRequest(symbol, typeVar, side, amount, price, params)
	var wallet string = "W001"
	var walletOption *string = SafeStringPtr(GetValue(TupleSlice(this.HandleOptionStringAndParams(params, "createOrder", "wallet", wallet)), 0))
	orderRequest = this.Extend(orderRequest, map[string]any{
		"wallet": walletOption,
	})

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostV1FapiTradePlaceOrder(orderRequest)).Raw))
	//
	//     {
	//         "code": 200,
	//         "message": "success",
	//         "data": {
	//             "wallet": "W001",
	//             "symbol": "ETH-USDT",
	//             "orderId": "7408875768086683648",
	//             "clientOrderId": "7408875768086683648",
	//             "price": "1000",
	//             "origQty": "10",
	//             "avgPrice": null,
	//             "executedQty": "0",
	//             "orderType": "LIMIT",
	//             "side": "BUY",
	//             "status": "NEW",
	//             "stopPrice": null,
	//             "activatePrice": null,
	//             "timeInForce": null,
	//             "workingType": "CONTRACT_PRICE",
	//             "positionSide": "BOTH",
	//             "priceProtect": false,
	//             "reduceOnly": false,
	//             "closePosition": false,
	//             "createTime": "1766413633367",
	//             "updateTime": "1766413633367"
	//         },
	//         "success": true
	//     }
	//
	var data map[string]any = MapTyped(this.SafeDict(response, "data", map[string]any{}))

	ch <- this.ParseOrder(data, market)
	return nil
}
func (this *Bydfi) CreateOrderRequest(symbol any, typeVar any, side any, amount any, optionalArgs ...any) any {
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if IsEqual(typeVar, nil) {
		panic(ArgumentsRequired(this.Id + " requires a type argument"))
	}
	if IsEqual(side, nil) {
		panic(ArgumentsRequired(this.Id + " requires a side argument"))
	}
	var market map[string]any = this.Market(symbol)
	if IsEqual(side, nil) {
		panic(ArgumentsRequired(this.Id + " createOrderRequest() requires a side argument"))
	}
	var request map[string]any = map[string]any{
		"symbol": market["id"],
		"side":   ToUpper(side),
	}
	var stopLossPrice *string = this.SafeString(params, "stopLossPrice")
	var isStopLossOrder bool = (stopLossPrice != nil)
	var takeProfitPrice *string = this.SafeString(params, "takeProfitPrice")
	var isTakeProfitOrder bool = (takeProfitPrice != nil)
	var trailingPercent *string = this.SafeString(params, "trailingPercent")
	var isTailingStopOrder bool = (trailingPercent != nil)
	var stopPrice any = nil
	var isStopOrTakeProfit bool = isStopLossOrder || isTakeProfitOrder
	var query any = params
	if isStopOrTakeProfit {
		query = this.Omit(params, []any{"stopLossPrice", "takeProfitPrice"})
	}
	if isStopOrTakeProfit {
		stopPrice = func() any {
			if isStopLossOrder {
				return stopLossPrice
			}
			return takeProfitPrice
		}()
		request["stopPrice"] = this.PriceToPrecision(symbol, stopPrice)
	} else if isTailingStopOrder {
		query = this.Omit(query, []any{"trailingPercent"})
		request["callbackRate"] = trailingPercent
		var trailingTriggerPrice any = DerefScalar(this.NumberToString(price))
		var trailingTriggerPricequeryVariable []any = this.HandleParamString(query, "trailingTriggerPrice", trailingTriggerPrice)
		trailingTriggerPrice = GetValue(trailingTriggerPricequeryVariable, 0)
		query = GetValue(trailingTriggerPricequeryVariable, 1)
		if trailingTriggerPrice != nil {
			request["activationPrice"] = this.PriceToPrecision(symbol, trailingTriggerPrice)
			query = this.Omit(query, []any{"trailingTriggerPrice"})
		}
	}
	var typeValue string = ToUpper(typeVar)
	var isMarketOrder bool = ((typeValue == "MARKET") || (typeValue == "STOP_MARKET") || (typeValue == "TAKE_PROFIT_MARKET") || (typeValue == "TRAILING_STOP_MARKET"))
	if isMarketOrder {
		if typeValue == "MARKET" {
			if isStopLossOrder {
				typeValue = "STOP_MARKET"
			} else if isTakeProfitOrder {
				typeValue = "TAKE_PROFIT_MARKET"
			} else if isTailingStopOrder {
				typeValue = "TRAILING_STOP_MARKET"
			}
		}
	} else {
		if price == nil {
			panic(ArgumentsRequired(this.Id + " createOrder() requires a price argument for a " + typeValue + " order"))
		}
		request["price"] = this.PriceToPrecision(symbol, price)
		if isStopLossOrder {
			typeValue = "STOP"
		} else if isTakeProfitOrder {
			typeValue = "TAKE_PROFIT"
		}
	}
	request["type"] = typeValue
	var hedged any = false
	var hedgedqueryVariable []any = this.HandleOptionBoolAndParams(query, "createOrder", "hedged", hedged)
	hedged = GetValue(hedgedqueryVariable, 0)
	query = GetValue(hedgedqueryVariable, 1)
	var reduceOnly *bool = this.SafeBool(query, "reduceOnly", false)
	if hedged == true {
		query = this.Omit(query, "reduceOnly")
		if IsEqual(side, "buy") {
			request["positionSide"] = func() string {
				if reduceOnly != nil && *reduceOnly == true {
					return "SHORT"
				}
				return "LONG"
			}()
		} else if IsEqual(side, "sell") {
			request["positionSide"] = func() string {
				if reduceOnly != nil && *reduceOnly == true {
					return "LONG"
				}
				return "SHORT"
			}()
		}
	}
	var closePosition *bool = this.SafeBool(query, "closePosition", false)
	if closePosition == nil || *closePosition != true {
		query = this.Omit(query, "closePosition")
		request["quantity"] = this.AmountToPrecision(symbol, amount)
	} else if (typeValue != "STOP_MARKET") && (typeValue != "TAKE_PROFIT_MARKET") {
		panic(NotSupported(this.Id + " createOrder() closePosition is only supported for stopLoss and takeProfit market orders"))
	}
	var timeInForce any = this.HandleTimeInForce(query)
	var postOnly bool = false
	var postOnlyqueryVariable []any = this.HandlePostOnly(isMarketOrder, (IsEqual(timeInForce, "POST_ONLY")), query)
	postOnly = GetValueBool(postOnlyqueryVariable, 0, false)
	query = GetValue(postOnlyqueryVariable, 1)
	if postOnly {
		timeInForce = "POST_ONLY"
	}
	if timeInForce != nil {
		request["timeInForce"] = timeInForce
		query = this.Omit(query, "timeInForce")
	}
	if isStopLossOrder || isTakeProfitOrder || isTailingStopOrder {
		var workingType any = "CONTRACT_PRICE"
		workingTypequeryVariable := TupleSlice(this.HandleOptionStringAndParams(query, "createOrder", "triggerPriceType", workingType))
		workingType = GetValue(workingTypequeryVariable, 0)
		query = GetValue(workingTypequeryVariable, 1)
		request["workingType"] = this.EncodeWorkingType(workingType)
	}
	return this.Extend(request, query)
}
func (this *Bydfi) EncodeWorkingType(workingType any) any {
	var types map[string]any = map[string]any{
		"markPrice":     "MARK_PRICE",
		"mark":          "MARK_PRICE",
		"contractPrice": "CONTRACT_PRICE",
		"contract":      "CONTRACT_PRICE",
		"last":          "CONTRACT_PRICE",
	}
	return this.SafeString(types, workingType, workingType)
}

/**
 * @method
 * @name bydfi#createOrders
 * @description create a list of trade orders
 * @see https://developers.bydfi.com/en/futures/trade#batch-order-placement
 * @param {Array} orders list of orders to create, each object should contain the parameters required by createOrder, namely symbol, type, side, amount, price and params
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.wallet] The unique code of a sub-wallet. W001 is the default wallet and the main wallet code of the contract
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Bydfi) CreateOrdersAsync(orders any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrdersBody(ch, orders, optionalArgs...)
	return ch
}
func (this *Bydfi) createOrdersBody(ch chan any, orders any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var length int = GetArrayLength(orders)
	if length > 5 {
		panic(BadRequest(this.Id + " createOrders() accepts a maximum of 5 orders"))
	}
	var ordersRequests []any = []any{}
	for i := 0; i < GetArrayLength(orders); i++ {
		var rawOrder map[string]any = SafeMapTyped(orders, i)
		var symbol *string = this.SafeString(rawOrder, "symbol")
		var typeVar *string = this.SafeString(rawOrder, "type")
		var side *string = this.SafeString(rawOrder, "side")
		var amount *float64 = this.SafeNumber(rawOrder, "amount")
		var price *float64 = this.SafeNumber(rawOrder, "price")
		var orderParams map[string]any = MapTyped(this.SafeDict(rawOrder, "params", map[string]any{}))
		var orderRequest map[string]any = MapTyped(this.CreateOrderRequest(symbol, typeVar, side, amount, price, orderParams))
		ordersRequests = append(ordersRequests, orderRequest)
	}
	var wallet string = "W001"
	walletOption, paramsWallet := this.HandleOptionStringAndParams(params, "createOrder", "wallet", wallet)
	var request map[string]any = map[string]any{
		"wallet": walletOption,
		"orders": ordersRequests,
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostV1FapiTradeBatchPlaceOrder(this.Extend(request, paramsWallet))).Raw))
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseOrders(data)
	return nil
}

