func (this *Bydfi) ParsePosition(position any, optionalArgs ...any) any {
	//
	// fetchPositions, fetchPositionsForSymbol
	//     {
	//         "symbol": "ETH-USDC",
	//         "side": "BUY",
	//         "volume": "0.001",
	//         "avgPrice": "3032.45",
	//         "liqPrice": "0",
	//         "markPrice": "3032.37",
	//         "unPnl": "-0.00008",
	//         "positionMargin": "0",
	//         "settleCoin": "USDC",
	//         "im": "3.03245",
	//         "mm": "0.007581125"
	//     }
	//
	// fetchPositionsHistory
	//     {
	//         "id": "16788366",
	//         "wallet": "W001",
	//         "currency": "USDC",
	//         "symbol": "ETH-USDC",
	//         "side": "BUY",
	//         "positionSide": "BOTH",
	//         "leverage": 1,
	//         "avgOpenPositionPrice": "3032.45",
	//         "openPositionVolume": "1",
	//         "openCount": 1,
	//         "highPrice": "3032.45",
	//         "lowPrice": "2953.67",
	//         "avgClosePositionPrice": "2953.67",
	//         "closePositionVolume": "1",
	//         "closePositionCost": "2.95367",
	//         "closeCount": 1,
	//         "positionProfits": "-0.07878",
	//         "lossBonus": "0",
	//         "capitalFeeTotal": "-0.00026361",
	//         "capitalFeeOutCash": "-0.00026361",
	//         "capitalFeeInCash": "0",
	//         "capitalFeeBonus": "0",
	//         "openFeeTotal": "-0.00181947",
	//         "openFeeBonus": "0",
	//         "closeFeeTotal": "-0.00177221",
	//         "closeFeeBonus": "0",
	//         "liqLoss": "0",
	//         "liqClosed": false,
	//         "sequence": "53685341336",
	//         "updateTime": "1766494929423",
	//         "createTime": "1766423985842"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "symbol")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var buyOrSell *string = this.SafeString(position, "side")
	var rawPositionSide *string = this.SafeStringLower(position, "positionSide")
	var positionSide *string = this.ParsePositionSide(buyOrSell)
	var hedged bool = false
	var isFetchPositionsHistory bool = false
	if rawPositionSide != nil {
		isFetchPositionsHistory = true
		if rawPositionSide == nil || *rawPositionSide != "both" {
			positionSide = rawPositionSide
			hedged = true
		} else {
			hedged = false
		}
	}
	var contractSize *string = this.SafeString(marketResolved, "contractSize")
	var contracts *string = this.SafeString2(position, "volume", "openPositionVolume")
	if !isFetchPositionsHistory {
		// in fetchPositions, the 'volume' is in base currency units, need to convert to contracts
		contracts = Precise.StringDiv(contracts, contractSize)
	}
	var timestamp *int64 = this.SafeInteger(position, "createTime")
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          this.SafeString(position, "id"),
		"symbol":                      marketResolved["symbol"],
		"entryPrice":                  this.ParseNumber(this.SafeString2(position, "avgOpenPositionPrice", "avgPrice")),
		"markPrice":                   this.ParseNumber(this.SafeString(position, "markPrice")),
		"lastPrice":                   this.ParseNumber(this.SafeString(position, "avgClosePositionPrice")),
		"notional":                    this.ParseNumber(this.SafeString(position, "closePositionCost")),
		"collateral":                  nil,
		"unrealizedPnl":               this.ParseNumber(this.SafeString(position, "unPnl")),
		"realizedPnl":                 this.ParseNumber(this.SafeString(position, "positionProfits")),
		"side":                        positionSide,
		"contracts":                   this.ParseNumber(contracts),
		"contractSize":                this.ParseNumber(contractSize),
		"timestamp":                   timestamp,
		"datetime":                    this.Iso8601(timestamp),
		"lastUpdateTimestamp":         this.SafeInteger(position, "updateTime"),
		"hedged":                      hedged,
		"maintenanceMargin":           this.ParseNumber(this.SafeString(position, "mm")),
		"maintenanceMarginPercentage": nil,
		"initialMargin":               this.ParseNumber(this.SafeString(position, "im")),
		"initialMarginPercentage":     nil,
		"leverage":                    this.ParseNumber(this.SafeString(position, "leverage")),
		"liquidationPrice":            this.ParseNumber(this.SafeString(position, "liqPrice")),
		"marginRatio":                 nil,
		"marginMode":                  nil,
		"percentage":                  nil,
	})
}
func (this *Bydfi) ParsePositionSide(side *string) *string {
	var sides map[string]any = map[string]any{
		"BUY":  "long",
		"SELL": "short",
	}
	return this.SafeString(sides, side, side)
}

/**
 * @method
 * @name bydfi#fetchPositionHistory
 * @description fetches historical positions
 * @see https://developers.bydfi.com/en/futures/trade#query-historical-position-profit-and-loss-records
 * @param {string} symbol a unified market symbol
 * @param {int} [since] timestamp in ms of the earliest position to fetch , params["until"] - since <= 7 days
 * @param {int} [limit] the maximum amount of records to fetch (default 500, max 500)
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest position to fetch , params["until"] - since <= 7 days
 * @param {string} [params.contractType] FUTURE or DELIVERY, default is FUTURE
 * @param {string} [params.wallet] The unique code of a sub-wallet. W001 is the default wallet and the main wallet code of the contract
 * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/?id=position-structure}
 */
func (this *Bydfi) FetchPositionHistoryAsync(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchPositionHistoryBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bydfi) fetchPositionHistoryBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var contractType string = "FUTURE"
	contractTypeOption, paramsContractType := this.HandleOptionStringAndParams(params, "fetchPositionHistory", "contractType", contractType)
	var request map[string]any = map[string]any{
		"symbol":       market["id"],
		"contractType": contractTypeOption,
	}
	var paramsSinceAndUntil any = this.HandleSinceAndUntil("fetchPositionsHistory", since, paramsContractType)
	if limit != nil {
		request["limit"] = limit
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivateGetV1FapiTradePositionHistory(this.Extend(request, paramsSinceAndUntil))).Raw))
	//
	//
	var data []any = SafeListTypedDefault(response, "data", []any{})
	var positions any = this.ParsePositions(data)

	ch <- this.FilterBySinceLimit(positions, since, limit)
	return nil
}

