/**
 * @method
 * @name bydfi#setMarginMode
 * @description set margin mode to 'cross' or 'isolated'
 * @see https://developers.bydfi.com/en/futures/user#change-margin-type-cross-margin
 * @param {string} marginMode 'cross' or 'isolated'
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.contractType] FUTURE or DELIVERY, default is FUTURE
 * @param {string} [params.wallet] The unique code of a sub-wallet. W001 is the default wallet and the main wallet code of the contract
 * @returns {object} response from the exchange
 */
func (this *Bydfi) SetMarginModeAsync(marginMode any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.setMarginModeBody(ch, marginMode, optionalArgs...)
	return ch
}
func (this *Bydfi) setMarginModeBody(ch chan any, marginMode any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " setMarginMode() requires a symbol argument"))
	}
	var marginModeValue string = ToLower(marginMode)
	if (marginModeValue != "isolated") && (marginModeValue != "cross") {
		panic(BadRequest(this.Id + " setMarginMode() marginMode argument should be isolated or cross"))
	}
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var contractType string = "FUTURE"
	contractTypeOption, paramsContractType := this.HandleOptionStringAndParams(params, "setMarginMode", "contractType", contractType)
	var wallet string = "W001"
	walletOption, paramsWallet := this.HandleOptionStringAndParams(paramsContractType, "setMarginMode", "wallet", wallet)
	var request map[string]any = map[string]any{
		"contractType": contractTypeOption,
		"symbol":       market["id"],
		"marginType":   strings.ToUpper(marginModeValue),
		"wallet":       walletOption,
	}

	ch <- PanicOnError((<-this.PrivatePostV1FapiUserDataMarginType(this.Extend(request, paramsWallet))).Raw)
	return nil
}

