func (this *Bydfi) FetchTransactionsHelperAsync(typeVar string, code any, since any, limit any, params any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTransactionsHelperBody(ch, typeVar, code, since, limit, params)
	return ch
}
func (this *Bydfi) fetchTransactionsHelperBody(ch chan any, typeVar string, code any, since any, limit any, params any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var methodName string = "fetchWithdrawals"
	if typeVar == "deposit" {
		methodName = "fetchDeposits"
	}
	if IsEqual(code, nil) {
		panic(ArgumentsRequired(this.Id + " " + methodName + "() requires a code argument"))
	}
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	var paginate *bool = this.SafeBool(params, "paginate", false)
	if paginate != nil && *paginate == true {
		var maxLimit int = 50
		var paramsPaginate map[string]any = this.Extend(this.Omit(params, "paginate"), map[string]any{
			"paginationDirection": "backward",
		})

		var paginatedResponse []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallDynamicAsync(methodName, currency["code"], since, limit, paramsPaginate, maxLimit, true))))

		ch <- this.SortBy(paginatedResponse, "timestamp")
		return nil
	}
	var request map[string]any = map[string]any{
		"asset": currency["id"],
	}
	var until any = nil
	var paramsUntil any = nil
	var untilparamsUntilVariable []any = this.HandleOptionIntegerAndParams2(params, "fetchTransfers", "until", "endTime")
	until = GetValue(untilparamsUntilVariable, 0)
	paramsUntil = GetValue(untilparamsUntilVariable, 1)
	var now int64 = this.Milliseconds()
	var sevenDays int64 = (7 * 24) * 60 * 60 * 1000 // the maximum range is 7 days
	var startTime any = since
	if IsEqual(startTime, nil) {
		if IsEqual(until, nil) {
			// both since and until are undefined
			startTime = now - sevenDays
			until = now
		} else {
			// since is undefined but until is defined
			startTime = Subtract(until, sevenDays)
		}
	} else if IsEqual(until, nil) {
		// until is undefined but since is defined
		var delta any = Subtract(now, startTime)
		if IsGreaterThan(delta, sevenDays) {
			until = Add(startTime, sevenDays)
		} else {
			until = now
		}
	}
	request["startTime"] = startTime
	request["endTime"] = until
	if !IsEqual(limit, nil) {
		request["limit"] = limit
	}
	var response map[string]any = nil
	if typeVar == "deposit" {
		//
		//     {
		//         "code": 200,
		//         "message": "success",
		//         "data": [
		//             {
		//                 "orderId": "1208864446987255809",
		//                 "asset": "USDC",
		//                 "amount": "200",
		//                 "status": "SUCCESS",
		//                 "txId": "0xd059a82a55ffc737722bd23c1ef3db2884ce8525b72ff0b3c038b430ce0c8ca5",
		//                 "network": "ETH",
		//                 "address": "0x8346b46f6aa9843c09f79f1c170a37aca83c8fcd",
		//                 "addressTag": null,
		//                 "finishTime": 1766145475000,
		//                 "createTime": 1766145344000
		//             }
		//         ],
		//         "success": true
		//     }
		//

		response = MapTyped(PanicOnError((<-this.PrivateGetV1SpotDepositRecords(this.Extend(request, paramsUntil))).Raw))
	} else {
		//
		// todo check after withdrawal
		//

		response = MapTyped(PanicOnError((<-this.PrivateGetV1SpotWithdrawRecords(this.Extend(request, paramsUntil))).Raw))
	}
	var data []any = SafeListTypedDefault(response, "data", []any{})
	var transactionParams map[string]any = map[string]any{
		"type": typeVar,
	}
	var paramsTransaction map[string]any = this.Extend(paramsUntil, transactionParams)

	ch <- this.ParseTransactions(data, currency, since, limit, paramsTransaction)
	return nil
}
func (this *Bydfi) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//     {
	//         "orderId": "1208864446987255809",
	//         "asset": "USDC",
	//         "amount": "200",
	//         "status": "SUCCESS",
	//         "txId": "0xd059a82a55ffc737722bd23c1ef3db2884ce8525b72ff0b3c038b430ce0c8ca5",
	//         "network": "ETH",
	//         "address": "0x8346b46f6aa9843c09f79f1c170a37aca83c8fcd",
	//         "addressTag": null,
	//         "finishTime": 1766145475000,
	//         "createTime": 1766145344000
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var currencyId *string = this.SafeString(transaction, "asset")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var rawStatus *string = this.SafeStringLower(transaction, "status")
	var timestamp *int64 = this.SafeInteger(transaction, "createTime")
	var fee map[string]any = nil
	var feeCost *float64 = this.SafeNumber(transaction, "fee")
	if feeCost != nil {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": nil,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "orderId"),
		"txid":        this.SafeString(transaction, "txId"),
		"type":        nil,
		"currency":    code,
		"network":     this.NetworkIdToCode(this.SafeString(transaction, "network"), code),
		"amount":      this.SafeNumber(transaction, "amount"),
		"status":      this.ParseTransactionStatus(rawStatus),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     this.SafeString(transaction, "address"),
		"addressFrom": nil,
		"addressTo":   nil,
		"tag":         this.SafeString(transaction, "addressTag"),
		"tagFrom":     nil,
		"tagTo":       nil,
		"updated":     this.SafeInteger(transaction, "finishTime"),
		"comment":     nil,
		"fee":         fee,
		"internal":    false,
	}
}
func (this *Bydfi) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"success": "ok",
		"wait":    "pending",
		"failed":  "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bydfi) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	var body *string = GetArgStringPtr(optionalArgs, 4, nil)
	_ = body
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), api)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url any = apiUrl
	var endpoint string = "/" + path
	var query string = ""
	var sortedParams map[string]any = this.Keysort(params)
	if method == "GET" {
		query = this.Urlencode(sortedParams)
		if len(query) != 0 {
			endpoint += "?" + query
		}
	}
	var requestBody any = nil
	var requestHeaders any = nil
	if IsEqual(api, "private") {
		this.CheckRequiredCredentials()
		var timestamp string = strconv.FormatInt(this.Milliseconds(), 10)
		if method == "GET" {
			var payload any = Add(Add(this.ApiKey, timestamp), query)
			var signature string = this.Hmac(this.Encode(payload), this.Encode(this.Secret), sha256, "hex")
			requestHeaders = map[string]any{
				"X-API-KEY":       this.ApiKey,
				"X-API-TIMESTAMP": timestamp,
				"X-API-SIGNATURE": signature,
			}
		} else {
			requestBody = this.Json(sortedParams)
			var payload any = Add(Add(this.ApiKey, timestamp), requestBody)
			var signature string = this.Hmac(this.Encode(payload), this.Encode(this.Secret), sha256, "hex")
			requestHeaders = map[string]any{
				"Content-Type":    "application/json",
				"X-API-KEY":       this.ApiKey,
				"X-API-TIMESTAMP": timestamp,
				"X-API-SIGNATURE": signature,
			}
		}
	}
	url = Add(url, endpoint)
	var bodyResolved any = func() any {
		if requestBody == nil {
			return body
		}
		return requestBody
	}()
	var headersResolved any = func() any {
		if requestHeaders == nil {
			return headers
		}
		return requestHeaders
	}()
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersResolved,
	}
}
func (this *Bydfi) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsEqual(response, nil) {
		return nil // fallback to default error handler
	}
	//
	//     {
	//         "code": 101107,
	//         "message": "Requires transaction permissions"
	//     }
	//
	var code *string = this.SafeString(response, "code")
	var message *string = this.SafeString(response, "message")
	if code == nil || *code != "200" {
		var feedback *string = SafeStringPtr(Add(this.Id+" ", body))
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewBydfi(userConfig map[string]any) *Bydfi {
	p := newBydfi()
	p.Init(userConfig)
	return p
}

func (this *Bydfi) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

